questionvariables.text:
/*Defining question variables*/
x_1:rand(7)-3;
x_2:x_1+3;
x_3:x_1;
x_4:x_1-3;
y_1:rand(7)-3;
y_2:y_1+3;
y_3:y_2+3;
y_4:y_1+3;
coord_1:[x_1,y_1];
coord_2:[x_2,y_2];
coord_3:[x_3,y_3];
coord_4:[x_4,y_4];
grad1:(y_2-y_1)/(x_2-x_1);
grad2:(y_3-y_2)/(x_3-x_2);
grad3:(y_3-y_4)/(x_3-x_4);
grad4:(y_1-y_4)/(x_1-x_4);
y_intercept1:y_2-grad1*x_2;
y_intercept2:y_3-grad1*x_3;
y_intercept3:y_4-grad1*x_4;
y_intercept4:y_1-grad1*x_1;
eqn_y1:grad1*x+y_intercept1;
eqn_y2:grad2*x+y_intercept2;
eqn_y3:grad3*x+y_intercept3;
eqn_y4:grad4*x+y_intercept4;
ax1:rand(7)-4;
ay1:rand(7)-4;
ax2:rand(7)-4;
ay2:rand(7)-4;
ax3:rand(7)-4;
ay3:rand(7)-4;
ax4:rand(7)-4;
ay4:rand(7)-4;

/*Model answer*/
ta1:y_intercept1;
ta2:y_intercept2;
ta3:y_intercept3;
ta4:y_intercept4;
ta5:[ta1,ta2];
ta6:[ta3,ta2];
ta7:[ta1,ta4];
ta8:[ta3,ta4];

